from PIL import Image,ImageDraw,ImageFont
from cunfa_input_scale_train_20261116 import ROOT,OLD,TRAIN,CONTEXT,ARMS,read,write,sha
def main():
 res=read(ROOT/'results.json');p=res['protocol'];manifest=read(ROOT/'train_test_manifest.json');rows=manifest['test'];assert sha(TRAIN/'input_manifest.json')==p['train_manifest_sha256'];assert sha(OLD/'test_manifest.json')==p['test_manifest_sha256'];assert sha(Path(__file__).with_name('cunfa_input_scale_train_20261116.py'))==p['script_sha256'];assert sha(Path(__file__).resolve().parents[1]/'gongbi_training/cunfa_input_scale.py')==p['input_module_sha256'];assert sha(OLD/'frozen/context_head_exploratory.joblib')==p['old_head_sha256'];assert all(sha(ROOT/(a+'.joblib'))==res['head_hashes'][a] for a in ARMS);assert not res['historical_baseline_prediction_changes']
 context=read(ROOT/'context_probe_results.json');cp=read(ROOT/'context_probe_protocol.json');assert sha(ROOT/'fixed_extent.joblib')==cp['model_sha256'];assert sha(CONTEXT/'comparison_manifest.json')==cp['manifest_sha256'];native=read(CONTEXT/'native_probe.json');larger=read(CONTEXT/'larger_variant_probe.json');oldsrc={r['id']:r for r in read(OLD/'source_manifest.json')};assert all(r['status']=='unavailable' for r in larger);assert all(max(r['size'])<max(oldsrc[r['id']]['images'][0]['size']) for r in native)
 records=[]
 for r in rows:
  Image.open(r['image']).save(ROOT/'views'/(r['id']+'_source_local.png'));large=ROOT/'views'/(r['id']+'_larger_rock_context_source.png');fallback=OLD/'inputs'/(r['id']+'_context.png')
  if not large.exists():Image.open(fallback).save(large)
  rec=dict(id=r['id'],artist=r['artist_group'],work=r['work_id'],source_url=r['source_url'],source_label=r['label'],source='views/'+r['id']+'_source_local.png',native_input='views/'+r['id']+'_native_extent_local.png',fixed_input='views/'+r['id']+'_fixed_extent_local.png',rock_context='views/'+large.name,rock_context_is_assistant_window=r['publisher']=='DPM',native_size=list(Image.open(r['image']).size),predictions={a:next(x for x in res['results'][a]['records'] if x['id']==r['id']) for a in ARMS});records.append(rec)
 # Same aspect ratio enlargement for side-by-side model inputs, never fake high-res sources.
 change=next(r for r in records if r['id']=='fresh_231531_1');b=Image.new('RGB',(1200,410),'#f4f1e8');d=ImageDraw.Draw(b);font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',18)
 for j,(path,title) in enumerate([(change['source'],'原始75×80像素局部'),(change['native_input'],'旧输入：小图留在224画布中央'),(change['fixed_input'],'新输入：等比统一内容范围'),(change['rock_context'],'较完整岩面参考窗口')]):
  im=Image.open(ROOT/path).convert('RGB');scale=min(285/im.width,300/im.height);im=im.resize((round(im.width*scale),round(im.height*scale)),Image.Resampling.NEAREST);b.paste(im,(j*300+5,42));d.text((j*300+5,7),title,font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',15),fill='#294735')
 d.text((7,354),'仅修正网络输入表示；插值没有增加原图真实细节，也不是新画出的皴法。',font=font,fill='#875238');b.save(ROOT/'input_change.jpg',quality=94)
 # Preserve every remaining error, including all small axe-cut cases.
 errors=[r for r in records if not r['predictions']['fixed_extent']['agreement']];board=Image.new('RGB',(1000,len(errors)*240+55),'#f4f1e8');draw=ImageDraw.Draw(board)
 for i,r in enumerate(errors):
  im=Image.open(ROOT/r['source']);scale=min(210/im.width,190/im.height);im=im.resize((round(im.width*scale),round(im.height*scale)),Image.Resampling.NEAREST);board.paste(im,(5,i*240+30));draw.text((5,i*240+4),r['id'],font=font,fill='#294735');draw.text((240,i*240+48),'来源暂标：'+r['source_label']+'；新分类器：'+r['predictions']['fixed_extent']['prediction'],font=font,fill='#875238');draw.text((240,i*240+94),'标签仍需逐局部复核；不能用整幅说明替代真实分笔。',font=font,fill='#875238')
 draw.text((7,len(errors)*240+8),'全部5个剩余错例；其中夏圭4个小斧劈候选仍未找回。',font=font,fill='#875238');board.save(ROOT/'remaining_errors.jpg',quality=94)
 write('report_data.json',dict(records=records,summary={a:{k:v for k,v in res['results'][a].items() if k!='records'} for a in ARMS},context=context,metadata=res['input_metadata'],native_probe=native,larger_probe=larger))
 check=read(ROOT/'verification.json');check.update(training_and_test_source_hashes_match=True,both_head_hashes_match=True,historical_predictions_reproduced=True,larger_context_same_head_no_fit=True,first_failed_context_attempt_not_used=True,all13_cases_in_main_result=True,all5_remaining_errors_visible=True,no_native_higher_resolution_claim=True,model_adopted=False,independent_acceptance=False);write('verification.json',check)
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>皴法输入尺度修正与岩面上下文对照</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f1e8;color:#294735;font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:29px}.note{padding:15px;background:#fff8e8;border-left:5px solid #b77d44}.warn{color:#875238}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{min-width:0;background:#fffdf8;border:1px solid #d3d9ca;padding:10px}img{max-width:100%;height:auto;display:block;margin:auto}select{width:650px;max-width:100%;font:inherit;padding:8px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:9px;text-align:left;border-bottom:1px solid #d1d6c7}a{color:#236b61}@media(max-width:700px){main{padding:14px}.grid{grid-template-columns:1fr}h1{font-size:24px}}</style><main><small>2026-11-16 · 皴法分类输入修正 · 两组分类头训练</small><h1>修正小裁剪的输入占位，继续检查具体皴法短板</h1><p class="note"><b>同一63例训练、同一冻结编码器与SVM参数，已知13局部与来源暂标一致的数量由7增至8。</b>找回王时敏的一例，没有新增分类退步；夏圭4个小斧劈候选仍全部判为披麻。扩大为较完整岩面窗口后，9个故宫局部仍为5个对应，未带来额外改善。本轮不替换绘画版本，不宣称真正理解皴法。</p><h2>1. 本轮修改了什么</h2><img src="input_change.jpg"><p>旧预处理只缩小大图，小局部不放大就置于224×224画布中央。75×80局部的内容矩形只占画布约12%；新输入保持长宽比，统一长边至224，同样局部的内容矩形占约94%。灰度均衡、填充颜色、归一化、冻结编码器及分类器C=1均保持相同。插值只改变网络输入尺度，不会补回缺失的真实笔迹。</p><div class="scroll"><table><thead><tr><th>两组同条件训练</th><th>与来源暂标一致</th><th>比例</th></tr></thead><tbody id="metrics"></tbody></table></div><p class="warn">这是已反复查看的13例回归，标签主要来自作品说明及助手局部筛选，不是专家逐笔真值。两组头只用原63例训练，检查图作者和源图未进入该训练集；仍不能将一次小幅变化称独立泛化通过。混合／未知辨识、完整笔组与笔触生成没有训练。</p><h2>2. 逐张看原图与真实网络输入</h2><select id="case"></select><p id="scope"></p><div class="grid"><div class="card"><b>原始局部</b><img id="source"></div><div class="card"><b>旧尺度网络输入</b><img id="native_input"></div><div class="card"><b>统一尺度网络输入</b><img id="fixed_input"></div><div class="card"><b>岩面／邻域参考，非自动实例</b><img id="rock_context"></div></div><p id="refnote">参考窗口，无完整对象边界真值；网络输入图不是生成或复刻皴法的效果。</p><p id="prediction"></p><div class="scroll"><table><thead><tr><th>局部</th><th>来源暂标</th><th>旧尺度</th><th>统一尺度</th></tr></thead><tbody id="cases"></tbody></table></div><h2>3. 不同作品中的表现</h2><div class="scroll"><table><thead><tr><th>作品候选</th><th>局部数</th><th>旧尺度对应数</th><th>统一尺度对应数</th></tr></thead><tbody id="works"></tbody></table></div><p>王时敏4/4、马远1/1、夏圭0/4、文徵明3/4。数目少、同一作品多裁剪，不能将其当作13件独立作品；作品层级说明也不能自动证明每处局部都为单一皴法。</p><h2>4. 岩面上下文对照</h2><details><summary>查看整幅中的原局部与岩面窗口</summary><img src="object_context_review.jpg"></details><div class="scroll"><table><thead><tr><th>同一新分类头</th><th>9个故宫局部对应数</th></tr></thead><tbody id="context_metrics"></tbody></table></div><p>较完整岩面窗口由助手看原图选取，并在新预测前冻结；不是模型自主发现的完整石头实例。局部不变，只替换邻域。两种输入均5/9，夏圭4例仍错，说明单独扩大窗口未解决这批小斧劈错误。4个台北故宫局部未纳入这个9例对照，但始终保留在主13例结果中。</p><p>第一次混合输入对照的严格特征复现检查失败，结果未使用。单独重跑原13例可逐项复现旧特征；本轮另在同一运行条件下重训两头，再逐分支提取上下文特征，检查基线对应。未将复现异常当作算法收益。</p><h2>5. 全部剩余错例</h2><img src="remaining_errors.jpg"><p>现有表示仍不能稳定区分小斧劈与披麻。后续应核查局部方法是否单一、短笔／块面与组排列是否清楚，以及纸纹、染墨和苔点是否干扰；不能直接把这5个错例或模型输出当新训练标准答案。</p><h2>6. 原始清晰度核查</h2><p>故宫已有来源长边为1024，本轮尝试的公开无尺寸后缀版本长边仅539；2048版本均404。没有获得真正更高清来源，没有将插值放大算作新画作或新增细节。已有13个局部原生宽70–100像素；部分细节不足仍是限制。</p><div class="scroll"><table><thead><tr><th>作品</th><th>原公开预览</th><th>另一公开版本</th><th>2048版本</th></tr></thead><tbody id="quality"></tbody></table></div><p>来源：<a href="https://www.dpm.org.cn/collection/paint/231531.html">王时敏山水图</a>、<a href="https://www.dpm.org.cn/collection/paint/234350.html">马远梅石溪凫图</a>、<a href="https://www.dpm.org.cn/collection/paint/230757.html">夏圭雪堂客话图</a>。馆方皴法说明用于作品层级依据，局部分笔仍须独立参考。</p><h2>7. 四项目标的当前阶段</h2><p>本轮专注皴法输入和分类头，不继续追加泛分区训练。分区保持关键错例回修，树木画法训练保持关闭，待对象与皴法通过后再启动。完整轮廓、真实笔组、粗细浓淡、对象笔序和同风格创作仍需逐层验证；本轮未连接机械臂。</p><p><a href="protocol.json">两组训练协议</a> · <a href="results.json">全部13例与两模型结果</a> · <a href="context_probe_protocol.json">上下文对照协议</a> · <a href="context_probe_results.json">上下文完整结果</a> · <a href="verification.json">验证记录</a></p></main><script>let D;const $=s=>document.getElementById(s),pct=x=>(x*100).toFixed(1)+'%';function show(){let r=D.records[$('case').selectedIndex];for(let k of ['source','native_input','fixed_input','rock_context'])$(k).src=r[k];$('scope').textContent=r.id+' / 原生'+r.native_size.join('×')+'像素 / '+(r.rock_context_is_assistant_window?'助手岩面窗口':'既有邻域参考');$('prediction').textContent='来源暂标：'+r.source_label+'；旧尺度：'+r.predictions.native_extent.prediction+'；统一尺度：'+r.predictions.fixed_extent.prediction;}fetch('report_data.json').then(r=>r.json()).then(d=>{D=d;for(let r of d.records){let o=document.createElement('option');o.textContent=r.id;$('case').append(o)}$('case').onchange=show;show();for(let [a,n] of [['native_extent','旧尺度同条件重训'],['fixed_extent','统一尺度候选']]){let v=d.summary[a],tr=document.createElement('tr');tr.innerHTML='<td>'+n+'</td><td>'+v.agreement_count+'/'+v.regions+'</td><td>'+pct(v.source_label_agreement)+'</td>';$('metrics').append(tr)}for(let r of d.records){let tr=document.createElement('tr');tr.innerHTML='<td>'+r.id+'</td><td>'+r.source_label+'</td><td>'+r.predictions.native_extent.prediction+'</td><td>'+r.predictions.fixed_extent.prediction+'</td>';$('cases').append(tr)}for(let [w,v] of Object.entries(d.summary.fixed_extent.per_work)){let tr=document.createElement('tr');tr.innerHTML='<td>'+w+'</td><td>'+v.regions+'</td><td>'+d.summary.native_extent.per_work[w].agreement_count+'</td><td>'+v.agreement_count+'</td>';$('works').append(tr)}for(let [a,n] of [['standard_context','局部＋原2.5倍邻域'],['larger_rock_context','局部＋较完整岩面窗口']]){let v=d.context.summary[a],tr=document.createElement('tr');tr.innerHTML='<td>'+n+'</td><td>'+v.agreement_count+'/'+v.regions+'</td>';$('context_metrics').append(tr)}let oldsize={'231531':'490×1024','234350':'1024×970','230757':'1024×982'};for(let r of d.native_probe){let tr=document.createElement('tr');tr.innerHTML='<td>'+r.id+'</td><td>'+oldsize[r.id]+'</td><td>'+r.size.join('×')+'</td><td>未取得，404</td>';$('quality').append(tr)}window.reportReady=true});</script></html>'''
 (ROOT/'index.html').write_text(page,encoding='utf8')
 server=Path(__file__).with_name('serve_guohua_objects_v2_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','cunfa_input_scale_20261116');a=server.index('ALLOWED={');b=server.index('\nALLOWED.update',a);server=server[:a]+"ALLOWED={'index.html','input_change.jpg','remaining_errors.jpg','object_context_review.jpg','report_data.json','protocol.json','results.json','context_probe_protocol.json','context_probe_results.json','verification.json'}"+server[b:];(ROOT/'object_context_review.jpg').write_bytes((CONTEXT/'object_context_review.jpg').read_bytes());(ROOT/'serve_report.py').write_text(server.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8')
 checker=Path(__file__).with_name('check_guohua_objects_v2_view_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','cunfa_input_scale_20261116').replace(')==27',')==13').replace('range(27)','range(13)').replace(')==6',')==2').replace('all27_observations_switch_and_load','all13_observations_switch_and_load').replace('metrics_six_rows','metrics_two_rows').replace("['protocol.json','results.json','selection_before_download.json','source_checked_cunfa_concepts.json','verification.json']","['protocol.json','results.json','context_probe_protocol.json','context_probe_results.json','verification.json']").replace("'expanded_control.pt','line_aware_aug.pt','../expanded_control.pt','predictions/H_14_expanded_control.npz'","'fixed_extent.joblib','native_extent.joblib','../fixed_extent.joblib','fixed_extent_features.npz'")
 checker=checker.replace("assert requests.post(url,timeout=5).status_code==405","assert js('document.querySelectorAll(\"#cases tr\").length')==13\n assert js('document.querySelectorAll(\"#context_metrics tr\").length')==2\n assert requests.post(url,timeout=5).status_code==405")
 (ROOT/'check_report.py').write_text(checker.replace('str(Path(__file__).resolve().parents[1])',repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8');print(json.dumps(check),flush=True)
